'use strict';

const { parseISODate, addDays } = require('./dates');
const { formatDate, formatMoney } = require('./format');

function dueDateLabel(invoice) {
  const due = addDays(parseISODate(invoice.issued), invoice.termsDays);
  return formatDate(due);
}

function summary(invoice) {
  const total = invoice.lines.reduce((sum, l) => sum + l.cents * l.qty, 0);
  return `Invoice ${invoice.number}: ${formatMoney(total)} due ${dueDateLabel(invoice)}`;
}

module.exports = { dueDateLabel, summary };

