const test = require('node:test');
const assert = require('node:assert');
const { dueDateLabel, summary } = require('../src/invoice');

const invoice = {
  number: 'INV-1001',
  issued: '2024-03-01',
  termsDays: 30,
  lines: [{ cents: 2500, qty: 2 }],
};

test('due date is issued date plus terms', () => {
  assert.strictEqual(dueDateLabel(invoice), '2024-03-31');
});

test('summary contains total and due date', () => {
  assert.strictEqual(summary(invoice), 'Invoice INV-1001: $50.00 due 2024-03-31');
});
